// ── STROKES CALCULATOR ────────────────────────────────────────────────────────
// Returns net strokes (positive = World gets strokes, negative = Richmond gets strokes)
function calcStrokes(format, worldIds, richmondIds, tees="W") {
  const hcKey = tees==="B" ? "hcB" : tees==="G" ? "hcG" : "hcW";
  const wHCs = worldIds.map(id => { const p = ALL_PLAYERS.find(p=>p.id===id); return p ? p[hcKey] : 0; });
  const rHCs = richmondIds.map(id => { const p = ALL_PLAYERS.find(p=>p.id===id); return p ? p[hcKey] : 0; });

  let wTeam = 0, rTeam = 0;

  if (format === "scramble") {
    // Average of both players' HCs, rounded normally (0.5 rounds up)
    wTeam = Math.round((wHCs.reduce((a,b)=>a+b,0)/wHCs.length) * 10) / 10;
    wTeam = wHCs.length ? Math.ceil((wHCs[0]+wHCs[1])/2) : 0;
    rTeam = rHCs.length ? Math.ceil((rHCs[0]+rHCs[1])/2) : 0;
  } else if (format === "alt") {
    // 60% lower + 40% higher
    const [wLo, wHi] = wHCs.length===2 ? [Math.min(...wHCs), Math.max(...wHCs)] : [wHCs[0],wHCs[0]];
    const [rLo, rHi] = rHCs.length===2 ? [Math.min(...rHCs), Math.max(...rHCs)] : [rHCs[0],rHCs[0]];
    wTeam = Math.round(wLo*0.6) + Math.round(wHi*0.4);
    rTeam = Math.round(rLo*0.6) + Math.round(rHi*0.4);
  } else if (format === "modalt") {
    // 75% lower + 25% higher
    const [wLo, wHi] = wHCs.length===2 ? [Math.min(...wHCs), Math.max(...wHCs)] : [wHCs[0],wHCs[0]];
    const [rLo, rHi] = rHCs.length===2 ? [Math.min(...rHCs), Math.max(...rHCs)] : [rHCs[0],rHCs[0]];
    wTeam = Math.round(wLo*0.75) + Math.round(wHi*0.25);
    rTeam = Math.round(rLo*0.75) + Math.round(rHi*0.25);
  } else if (format === "captains") {
    // 50% lower + 25% higher
    const [wLo, wHi] = wHCs.length===2 ? [Math.min(...wHCs), Math.max(...wHCs)] : [wHCs[0],wHCs[0]];
    const [rLo, rHi] = rHCs.length===2 ? [Math.min(...rHCs), Math.max(...rHCs)] : [rHCs[0],rHCs[0]];
    wTeam = Math.round(wLo*0.5) + Math.round(wHi*0.25);
    rTeam = Math.round(rLo*0.5) + Math.round(rHi*0.25);
  } else {
    // singles: raw difference per player
    return (wHCs[0] || 0) - (rHCs[0] || 0);
  }
  return wTeam - rTeam; // positive = World gets strokes from Richmond
}

// ── COURSE DATA ───────────────────────────────────────────────────────────────
// Devil's Knob – White tees SI by hole
const DK_FRONT_SI  = [11, 9, 5, 17, 7, 13, 1, 15, 3];  // holes 1-9,  index 0=H1
const DK_BACK_SI   = [2,  4, 14, 16, 12, 18, 8, 10, 6]; // holes 10-18, index 0=H10
// Stony Creek Monocan/Shamokin – White tees SI
const SC_FRONT_SI  = [5, 1, 13, 3, 11, 9, 17, 15, 7];   // holes 1-9,  index 0=H1
const SC_BACK_SI   = [12, 2, 16, 4, 8, 6, 18, 10, 14];  // holes 10-18 (Shamokin), index 0=H10
// Dogwood Trace (2025 venue) – retained for history
const DOGWOOD_FRONT_SI = [15, 7, 13, 3, 11, 1, 17, 5, 9];
const DOGWOOD_BACK_SI  = [18, 12, 8, 14, 2, 4, 6, 16, 10];
// Aliases for heatmap backward compat
const DEVILS_KNOB_SI = DK_FRONT_SI;
const STONY_CREEK_SI = SC_FRONT_SI;

// Returns Set of 0-indexed positions (0-8) that receive strokes.
// venue key selects the correct nine's SI array.
function getStrokeHoles(strokes, totalHoles, venue, match_nine) {
  if (!strokes || strokes <= 0) return new Set();
  let siArr;
  if (totalHoles === 9) {
    // nine field drives front/back selection; venue is now the friendly course name
    const isBack = match_nine && match_nine.includes("Back");
    if      (venue === "Devil's Knob")  siArr = isBack ? DK_BACK_SI : DK_FRONT_SI;
    else if (venue === "Stony Creek")   siArr = isBack ? SC_BACK_SI : SC_FRONT_SI;
    else                                siArr = DK_FRONT_SI;
  } else {
    siArr = [...DOGWOOD_FRONT_SI, ...DOGWOOD_BACK_SI];
  }
  const n = Math.min(strokes, siArr.length);
  const ranked = siArr.map((si, idx) => ({ idx, si })).sort((a,b) => a.si - b.si).slice(0, n);
  return new Set(ranked.map(h => h.idx));
}

function getPlayer(id) { return ALL_PLAYERS.find(p => p.id === id) ?? { name: id, team:"world", hc:0 }; }
function getPlayerName(id) { return getPlayer(id).name; }

function deriveMatchStatus(holes) {
  const total = holes.length; // 9 or 18
  let w = 0, r = 0, played = 0;
  for (let i = 0; i < total; i++) {
    if (holes[i] === null) break;
    played++;
    if (holes[i] === "world") w++;
    else if (holes[i] === "richmond") r++;
  }
  const lead = w - r, left = total - played;
  if (played === 0) return { status:"upcoming", lead:0, winner:null, score:"", pts:{world:0,richmond:0} };
  if (Math.abs(lead) > left) {
    const winner = lead > 0 ? "world" : "richmond";
    return { status:"complete", lead, winner,
      score: left === 0 ? `${Math.abs(lead)} UP` : `${Math.abs(lead)}&${left}`,
      pts: winner==="world" ? {world:1,richmond:0} : {world:0,richmond:1} };
  }
  if (played === total) {
    if (lead === 0) return { status:"complete", lead:0, winner:"halved", score:"Halved", pts:{world:0.5,richmond:0.5} };
    const winner = lead > 0 ? "world" : "richmond";
    return { status:"complete", lead, winner, score:`${Math.abs(lead)} UP`,
      pts: winner==="world" ? {world:1,richmond:0} : {world:0,richmond:1} };
  }
  return { status:"live", lead, winner:null,
    score: lead===0 ? "All Square" : `${lead>0?"World":"Richmond"} ${Math.abs(lead)} UP`,
    pts:{world:0,richmond:0} };
}

function getTotals(matches) {
  return matches.reduce((acc, m) => {
    const d = deriveMatchStatus(m.holes);
    return { world: acc.world+(d.pts?.world??0), richmond: acc.richmond+(d.pts?.richmond??0) };
  }, { world:0, richmond:0 });
}

