// ── HOLE SCORER ───────────────────────────────────────────────────────────────
function HoleScorer({ match, onClose, onUpdate, onLiveUpdate }) {
  const [holes, setHoles] = useState([...match.holes]);
  const live = deriveMatchStatus(holes);
  const lastPlayed = holes.reduce((acc, h, i) => h !== null ? i : acc, -1);
  const nextHole = lastPlayed + 1;
  const strokeHoles = getStrokeHoles(match.strokes, match.holes.length, match.venue, match.nine);
  const strokeTeam = match.strokesTo; // "world" | "richmond" | "none"

  function setHole(idx, val) {
    const updated = [...holes];
    updated[idx] = updated[idx] === val ? null : val;
    for (let i = idx + 1; i < match.holes.length; i++) updated[i] = null;
    setHoles(updated);
    if (onLiveUpdate) onLiveUpdate(updated);
  }

  const lead = live.lead ?? 0;
  const leaderColor = lead > 0 ? C.worldGold : lead < 0 ? C.richLight : C.halved;

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(5,12,25,0.75)", zIndex:200, display:"flex", alignItems:"flex-end" }} onClick={onClose}>
      <div onClick={e => e.stopPropagation()} style={{ background:C.card, width:"100%", borderRadius:"18px 18px 0 0", maxHeight:"92vh", overflowY:"auto", boxShadow:"0 -8px 40px rgba(0,0,0,0.2)" }}>
        <div style={{ position:"sticky", top:0, background:C.card, zIndex:10, padding:"16px 16px 12px", borderBottom:`1px solid ${C.border}` }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
            <div>
              <div style={{ color:C.muted, fontSize:11, fontWeight:700, letterSpacing:1.5 }}>
                {FORMATS[match.format] ?? match.format} · {match.venue} · {match.tees} Tees{match.teeTime ? ` · ${match.teeTime}` : ""}
              </div>
              <div style={{ fontSize:14, fontWeight:700, marginTop:3 }}>
                <span style={{ color:C.worldGold }}>{match.teamWorld.map(getPlayerName).map((n,i) => <span key={i} style={{ display:"block", lineHeight:1.4 }}>{n}</span>)}</span>
                <span style={{ color:C.muted }}> vs </span>
                <span style={{ color:C.richLight }}>{match.teamRichmond.map(getPlayerName).map((n,i) => <span key={i} style={{ display:"block", lineHeight:1.4 }}>{n}</span>)}</span>
              </div>
            </div>
            <button onClick={onClose} style={{ background:"none", border:"none", color:C.muted, fontSize:22, cursor:"pointer" }}>✕</button>
          </div>
          <div style={{ marginTop:12, padding:"10px 14px", background:C.cardAlt, borderRadius:10, display:"flex", justifyContent:"space-between", alignItems:"center" }}>
            <div>
              <div style={{ color:leaderColor, fontSize:17, fontWeight:800 }}>{live.score || "—"}</div>
              <div style={{ color:C.muted, fontSize:11 }}>{lead > 0 ? "World leads" : lead < 0 ? "Richmond leads" : live.status==="upcoming" ? "Not started" : "All Square"}</div>
              {/* Strokes given */}
              {match.strokes > 0 && match.strokesTo !== "none" && (
                <div style={{ marginTop:5, display:"inline-flex", alignItems:"center", gap:4,
                  background: match.strokesTo==="world" ? C.worldBg : C.richBg,
                  border: `1px solid ${match.strokesTo==="world" ? C.worldBorder : C.richBorder}`,
                  borderRadius:6, padding:"2px 8px" }}>
                  <span style={{ fontSize:10, fontWeight:700,
                    color: match.strokesTo==="world" ? C.worldGold : C.richLight }}>
                    {match.strokesTo==="world" ? "World" : "Richmond"} +{match.strokes} stroke{match.strokes!==1?"s":""}
                  </span>
                </div>
              )}
              {(!match.strokes || match.strokes===0) && (
                <div style={{ marginTop:5, color:C.muted, fontSize:10 }}>No strokes given</div>
              )}
            </div>
            <div style={{ textAlign:"right" }}>
              <div style={{ color:C.text, fontSize:12, fontWeight:600 }}>{lastPlayed+1}/{match.holes.length} holes</div>
              {live.status==="complete" && <div style={{ marginTop:3, fontSize:10, fontWeight:700, color:leaderColor, background:`${leaderColor}18`, borderRadius:6, padding:"2px 8px" }}>MATCH OVER</div>}
              {live.status==="live"     && <div style={{ marginTop:3, fontSize:10, fontWeight:700, color:C.live, background:"#dcfce7", borderRadius:6, padding:"2px 8px" }}>● LIVE</div>}
            </div>
          </div>
        </div>

        <div style={{ padding:"12px 16px" }}>
          <div style={{ color:C.muted, fontSize:11, fontWeight:700, letterSpacing:1.5, marginBottom:10 }}>TAP HOLE RESULT</div>
          {Array.from({ length:match.holes.length }, (_, i) => {
            const val = holes[i];
            const isLocked = live.status==="complete" && val===null;
            const isFuture = i > nextHole && live.status!=="complete";
            return (
              <div key={i} style={{ marginBottom:7, opacity: isLocked ? 0.25 : isFuture ? 0.4 : 1 }}>
                <div style={{ display:"flex", alignItems:"center", gap:8 }}>
                  <div style={{ width:34, flexShrink:0, display:"flex", flexDirection:"column", alignItems:"center", gap:1 }}>
                    <div style={{ color: i===nextHole ? C.text : C.muted, fontSize:13, fontWeight: i===nextHole?700:500 }}>{(match.holeStart||1)+i}</div>
                    {strokeHoles.has(i) && strokeTeam !== "none" && (
                      <div style={{
                        fontSize:8, fontWeight:800, letterSpacing:0.3,
                        color: strokeTeam==="world" ? C.worldGold : C.richLight,
                        background: strokeTeam==="world" ? C.worldBg : C.richBg,
                        borderRadius:3, padding:"1px 4px", lineHeight:1.4,
                      }}>{strokeTeam==="world"?"W+1":"R+1"}</div>
                    )}
                  </div>
                  <button onClick={() => !isLocked && setHole(i,"world")} disabled={isLocked} style={{ flex:1, padding:"10px 6px", borderRadius:9, border:"none", cursor:isLocked?"default":"pointer", fontWeight:700, fontSize:12, background:val==="world"?C.worldGold:C.subtle, color:val==="world"?"#000":C.muted, boxShadow:val==="world"?`0 0 10px ${C.worldGold}44`:"none", transition:"all 0.1s" }}>{val==="world"?"✓ World":"World"}</button>
                  <button onClick={() => !isLocked && setHole(i,"halved")} disabled={isLocked} style={{ width:58, padding:"10px 4px", borderRadius:9, border:"none", cursor:isLocked?"default":"pointer", fontWeight:700, fontSize:11, background:val==="halved"?"#d97706":C.subtle, color:val==="halved"?"#fff":C.muted, boxShadow:val==="halved"?"0 0 8px rgba(217,119,6,0.4)":"none", transition:"all 0.1s" }}>{val==="halved"?"✓ ½":"½"}</button>
                  <button onClick={() => !isLocked && setHole(i,"richmond")} disabled={isLocked} style={{ flex:1, padding:"10px 6px", borderRadius:9, border:"none", cursor:isLocked?"default":"pointer", fontWeight:700, fontSize:12, background:val==="richmond"?C.richBlue:C.subtle, color:val==="richmond"?"#fff":C.muted, boxShadow:val==="richmond"?`0 0 10px ${C.richBlue}44`:"none", transition:"all 0.1s" }}>{val==="richmond"?"✓ Rich":"Richmond"}</button>
                </div>
                {val !== null && (() => {
                  const snap = deriveMatchStatus(holes.slice(0,i+1));
                  return <div style={{ paddingLeft:34, marginTop:2 }}><span style={{ fontSize:10, fontWeight:600, color:snap.lead===0?C.muted:snap.lead>0?C.worldGold:C.richLight }}>{snap.lead===0?"All Square":snap.lead>0?`World ${snap.lead} UP`:`Richmond ${Math.abs(snap.lead)} UP`}</span></div>;
                })()}
              </div>
            );
          })}
        </div>

        <div style={{ padding:"8px 16px 32px", position:"sticky", bottom:0, background:C.card, borderTop:`1px solid ${C.border}` }}>
          <button onClick={() => { onUpdate({...match,holes}); onClose(); }} style={{ width:"100%", padding:14, borderRadius:12, border:"none", background:`linear-gradient(135deg, ${C.accent}, #0d6644)`, color:"#fff", fontWeight:800, fontSize:15, cursor:"pointer" }}>Save Scores</button>
        </div>
      </div>
    </div>
  );
}

// ── MATCH CARD ────────────────────────────────────────────────────────────────
function MatchCard({ match, onOpenScorer }) {
  const d = deriveMatchStatus(match.holes);
  const isLive = d.status==="live", isDone = d.status==="complete", isHalved = d.winner==="halved";
  const holesPlayed = match.holes.filter(h=>h!==null).length;
  // For live matches: color by who leads. For complete: color by winner. For halved: neutral.
  const scoreColor = isHalved
    ? C.halved
    : d.winner === "world"
      ? C.worldGold
      : d.winner === "richmond"
        ? C.richLight
        : isLive && d.lead > 0
          ? C.worldGold
          : isLive && d.lead < 0
            ? C.richLight
            : C.muted;

  return (
    <div onClick={() => onOpenScorer && onOpenScorer(match)} style={{ background:C.card, borderRadius:12, overflow:"hidden", border:`1px solid ${isLive?C.live:C.border}`, boxShadow: isLive?"0 0 0 2px rgba(21,128,61,0.18),0 2px 8px rgba(0,0,0,0.06)":"0 1px 4px rgba(0,0,0,0.07)", cursor: onOpenScorer ? "pointer" : "default" }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", padding:"7px 12px", background:C.cardAlt, borderBottom:`1px solid ${C.border}` }}>
        <span style={{ color:C.muted, fontSize:11, fontWeight:600 }}>
          {match.match ? `${match.match} · ` : match.round ? `${match.round} · ` : ""}{FORMATS[match.format]??match.format}{match.teeTime&&match.teeTime!=="TBD"?` · ${match.teeTime}`:match.teeTime==="TBD"?" · TBD":""}
          {match.venue?` · ${match.venue}`:match.tees?` · ${match.tees} Tees`:""}
        </span>
        <span style={{ fontSize:10, fontWeight:700, padding:"2px 8px", borderRadius:20, background:isLive?"#dcfce7":isDone?C.subtle:"#e8edf8", color:isLive?C.live:isDone?C.muted:"#6070bb" }}>
          {isLive&&"● "}{isDone?"Final":isLive?"LIVE":"Upcoming"}
        </span>
      </div>
      <div style={{ padding:"12px 12px 10px" }}>
        {/* Team panels */}
        <div style={{ display:"flex", alignItems:"stretch", gap:6 }}>
          {/* World */}
          <div style={{ flex:1, borderRadius:8, padding:"8px 10px", background:d.winner==="world"?C.worldBg:"transparent", border:`1px solid ${d.winner==="world"?C.worldBorder:"transparent"}` }}>
            <div style={{ color:C.worldGold, fontSize:10, fontWeight:700, marginBottom:2 }}>WORLD</div>
            <div style={{ fontSize:13, fontWeight:600 }}>{match.teamWorld.map(getPlayerName).map((n,i) => <div key={i} style={{ color:C.text, lineHeight:1.4 }}>{n}</div>)}</div>
            {match.strokes > 0 && match.strokesTo === "world" && (
              <div style={{ display:"inline-flex", alignItems:"center", gap:3, marginTop:5, background:"rgba(184,135,12,0.12)", borderRadius:5, padding:"2px 7px" }}>
                <span style={{ color:C.worldGold, fontSize:11, fontWeight:800 }}>+{match.strokes}</span>
                <span style={{ color:C.worldGold, fontSize:9, fontWeight:600 }}>strokes</span>
              </div>
            )}
          </div>

          {/* Center: score or vs + strokes indicator */}
          <div style={{ display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", minWidth:52, gap:4 }}>
            {(isDone||isLive)
              ? <><div style={{ color:scoreColor, fontSize:13, fontWeight:800, textAlign:"center" }}>{d.score}</div><div style={{ color:C.muted, fontSize:9 }}>{isHalved?"HALVED":d.winner==="world"?"WORLD":"RICH"}</div></>
              : <div style={{ color:C.subtle, fontSize:15 }}>vs</div>
            }
            {match.strokes === 0 && (
              <div style={{ fontSize:9, color:C.muted, fontWeight:600, letterSpacing:0.5 }}>EVEN</div>
            )}
          </div>

          {/* Richmond */}
          <div style={{ flex:1, borderRadius:8, padding:"8px 10px", textAlign:"right", background:d.winner==="richmond"?C.richBg:"transparent", border:`1px solid ${d.winner==="richmond"?C.richBorder:"transparent"}` }}>
            <div style={{ color:C.richLight, fontSize:10, fontWeight:700, marginBottom:2 }}>RICHMOND</div>
            <div style={{ fontSize:13, fontWeight:600 }}>{match.teamRichmond.map(getPlayerName).map((n,i) => <div key={i} style={{ color:C.text, lineHeight:1.4, textAlign:"right" }}>{n}</div>)}</div>
            {match.strokes > 0 && match.strokesTo === "richmond" && (
              <div style={{ display:"inline-flex", alignItems:"center", gap:3, marginTop:5, background:"rgba(46,120,200,0.1)", borderRadius:5, padding:"2px 7px" }}>
                <span style={{ color:C.richLight, fontSize:11, fontWeight:800 }}>+{match.strokes}</span>
                <span style={{ color:C.richLight, fontSize:9, fontWeight:600 }}>strokes</span>
              </div>
            )}
          </div>
        </div>

        {/* Hole progress strip */}
        <div style={{ marginTop:10 }}>
          <div style={{ display:"flex", gap:2 }}>
            {match.holes.map((h,i) => <div key={i} style={{ flex:1, height:5, borderRadius:2, background:h==="world"?C.worldGold:h==="richmond"?C.richBlue:h==="halved"?"#b0bcc8":C.subtle }} />)}
          </div>
          <div style={{ display:"flex", justifyContent:"space-between", marginTop:4 }}>
            <span style={{ color:C.muted, fontSize:10 }}>{holesPlayed}/{match.holes.length} · {match.nine||"9 holes"}</span>
            <span style={{ color:C.muted, fontSize:10, fontWeight:600 }}>{isDone?`${d.pts?.world??0}–${d.pts?.richmond??0} pts`:isLive?"In progress":"Tap to score"}</span>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── SORTABLE TABLE ────────────────────────────────────────────────────────────
function SortableTable({ cols, rows, defaultSort, teamColor }) {
  const [sortCol, setSortCol] = useState(defaultSort ?? cols[cols.length-1].key);
  const [sortDir, setSortDir] = useState("desc");

  function handleSort(key) {
    if (sortCol === key) setSortDir(d => d==="desc"?"asc":"desc");
    else { setSortCol(key); setSortDir("desc"); }
  }

  const sorted = [...rows].sort((a, b) => {
    const av = a[sortCol] ?? -1, bv = b[sortCol] ?? -1;
    return sortDir === "desc" ? bv - av : av - bv;
  });

  return (
    <div style={{ background:C.card, borderRadius:12, overflow:"hidden", border:`1px solid ${C.border}`, boxShadow:"0 1px 4px rgba(0,0,0,0.06)", marginBottom:20 }}>
      {/* Header */}
      <div style={{ display:"grid", gridTemplateColumns:cols.map(c=>c.w||"1fr").join(" "), background:C.cardAlt, borderBottom:`1px solid ${C.border}` }}>
        {cols.map(c => (
          <button key={c.key} onClick={() => handleSort(c.key)} style={{
            background:"none", border:"none", cursor:"pointer", padding:"9px 8px",
            textAlign: c.align || "center", display:"flex", alignItems:"center",
            justifyContent: c.align==="left" ? "flex-start" : "center", gap:3,
          }}>
            <span style={{ color: sortCol===c.key ? C.text : C.muted, fontSize:10, fontWeight:700 }}>{c.label}</span>
            {sortCol===c.key && <span style={{ color: sortCol===c.key ? C.accent : C.muted, fontSize:9 }}>{sortDir==="desc"?"▼":"▲"}</span>}
          </button>
        ))}
      </div>
      {/* Rows */}
      {sorted.map((row, i) => (
        <div key={row.id||i} style={{ display:"grid", gridTemplateColumns:cols.map(c=>c.w||"1fr").join(" "),
          borderBottom: i<sorted.length-1 ? `1px solid ${C.subtle}` : "none",
          background: i%2 ? "rgba(0,0,0,0.015)" : "transparent",
          opacity: row.alumni ? 0.72 : 1 }}>
          {cols.map(c => {
            const formatted = c.format ? c.format(row[c.key], row) : null;
            const isJSX = formatted !== null && typeof formatted === "object";
            return (
              <div key={c.key} style={{ padding:"9px 8px", textAlign:c.align||"center", alignSelf:"center",
                color: (!isJSX && c.color) ? c.color(row[c.key], row) : C.text,
                fontSize: c.key==="pts" ? 14 : 12, fontWeight: c.key==="pts" ? 800 : c.key==="name" ? 600 : 500 }}>
                {isJSX ? formatted : (formatted ?? row[c.key] ?? "—")}
              </div>
            );
          })}
        </div>
      ))}
    </div>
  );
}


